import {mountControl} from './control-ui.mjs';
import {mountDrawing,mountSensors} from './task-ui.mjs';
import {Day,JOB,MOMENTS,STEPS} from './model.mjs';
import {SpaceWork} from './space-model.mjs';
import {createWorld,STATIONS} from './world.mjs';
import {salaryDay,PAY_NOTE,won,RIASEC,MIN_WAGE,saveRecordSafe,loadMine,needsWhoCheck,keepSession,startNewSession,walletSummary,careernetUrl,currentSession} from './shared/workday.js';
import {mountSpace} from './space-ui.mjs';
import {openSendDialog} from './send-records.mjs';
const $=id=>document.getElementById(id),day=new Day(),work=new SpaceWork(),panel=$('panel');
let world=null,flat=new URLSearchParams(location.search).has('flat'),spaceSession=null,opening=false,atStation=false,moving=false,like=null,hard=null,saved=false,session=currentSession().id,radio='',position={x:0,z:2.4};
const home=/\/aerospace-day\/(index\.html)?$/.test(location.pathname)?'<a href="../">← 다른 일터 고르기</a>':'';
const button=(id,label)=>`<button class="wd-btn" id="${id}">${label}</button>`;
const pins=document.createElement('div');pins.id='stations';$('stage').append(pins);$('speech').remove();
function say(s){radio=s;if($('speech'))$('speech').textContent=s}
function show(s){panel.innerHTML=`<p id="speech" class="radio" role="status">${radio}</p>`+s;panel.scrollTop=0}
function wallet(){const w=walletSummary();return `<p>🔖 다녀온 직업 ${w.jobs.length}개 · ⏱ 일한 시간 ${Math.round(w.minutes/6)/10}시간<br><small>🪙 받은 일당 ${won(w.total)}</small></p>`}
function checkSession(){let active=null;try{active=JSON.parse(localStorage.getItem('workday-session-v1'))?.id}catch{}if(active&&active!==session){show('<h2>출근하는 사람이 바뀌었어요.</h2><p>다른 사람 기록에 이 하루를 넣지 않도록 새로 시작해요.</p>'+button('reload','새 사람으로 시작하기'));$('reload').onclick=()=>location.reload();return false}return true}
function modeButton(){$('flat').textContent=flat?'3D로 돌아가기':'평면 모드';$('flat').setAttribute('aria-pressed',String(flat))}
function initWorld(){if(world){position=world.getPosition();world.dispose()}$('world').hidden=flat;$('flatCanvas').hidden=!flat;
 const options={flat,position,onPins(list){pins.replaceChildren();for(const s of list){const b=document.createElement('button');b.className='station-pin'+(s.id===STEPS[day.stage].station?' current':'');b.dataset.station=s.id;b.textContent=s.name;if(s.id===STEPS[day.stage].station&&day.stage>0&&day.stage<10){const call=document.createElement('span');call.className='station-call';call.textContent='무전 도착';b.append(call);b.setAttribute('aria-label',s.name+' · 새 무전이 있어요')}b.style.left=s.x+'px';b.style.top=s.y+'px';b.onclick=()=>travel(s.id);pins.append(b)}},onMove(name){moving=true;say(`이동 중 · ${name}`);if($('goWork'))$('goWork').disabled=true},onArrive(id){moving=false;if(id===STEPS[day.stage].station&&day.stage>0&&day.stage<10){atStation=true;render()}else{say('지금 무전은 '+STATIONS.find(s=>s.id===STEPS[day.stage].station).name+'에서 기다리고 있어요.');if($('goWork'))$('goWork').disabled=false}}};
 try{world=createWorld(flat?$('flatCanvas'):$('world'),options)}catch(e){if(flat)throw e;flat=true;world=null;initWorld();return}world.setTask(STEPS[day.stage].station);modeButton();
}
function travel(id){if(!checkSession()||opening||spaceSession||day.stage===0||day.stage===10)return;atStation=false;world.go(id)}
$('flat').onclick=()=>{if(opening||spaceSession)return;flat=!flat;moving=false;initWorld();if(!atStation)render()};$('expand').onclick=()=>document.body.classList.toggle('expanded');
function tracker(){return `<details class="todo"><summary aria-label="하루 할 일">${STEPS.slice(1,10).map((s,i)=>`<span class="${i+1<day.stage?'done':''}" title="${s.time} ${s.name}">${i+1<day.stage?'●':'○'}</span>`).join(' ')} · 하루 할 일</summary><ol>${STEPS.slice(1,10).map((s,i)=>`<li>${s.time} ${s.name}${i+1<day.stage?' ✓':''}</li>`).join('')}</ol></details>`}
function hud(){const step=STEPS[day.stage],closing=day.stage===9&&day.reportChecked;const time=day.stage===10?`${18+Math.floor(day.overtime/60)}:${String(day.overtime%60).padStart(2,'0')}`:closing?'18:00':step.time;const [h,m]=time.split(':').map(Number),worked=day.stage===10?day.worked:Math.max(0,(h-9)*60+m-(day.stage>=6?60:0));$('clock').textContent=`항공우주공학 · ${time}${day.delay&&day.stage<10?' · '+day.delay+'분 밀림':''}`;$('money').textContent='🪙 오늘 번 일당 '+won(salaryDay(JOB.annual,worked,480).total)}
function advance(choice){if(!checkSession())return;const previousStation=STEPS[day.stage].station,wasAtStation=atStation;if(day.next(choice)){atStation=wasAtStation&&previousStation===STEPS[day.stage].station;moving=false;render()}}
function returnHall(){spaceSession?.dispose();spaceSession=null;opening=false;atStation=false;pins.hidden=false;$('flat').hidden=$('expand').hidden=false;initWorld();render()}
async function hands(mode){if(spaceSession||opening)return;opening=true;world.pause(true);$('world').hidden=$('flatCanvas').hidden=pins.hidden=true;$('flat').hidden=$('expand').hidden=true;
 const created=await mountSpace({stage:$('stage'),panel,flat,work,mode,baseDelay:mode==='assembly'?day.drawingDelay:day.delay,checkSession,onModeChange:v=>flat=v,onExit:returnHall,onComplete:result=>{
  let ok=false;if(mode==='prepare')ok=day.prepare();else if(mode==='assembly')ok=day.assemble(result.repaired);else ok=day.completeSpace(result);
  if(ok){spaceSession?.dispose();spaceSession=null;opening=false;day.next();atStation=false;pins.hidden=false;$('flat').hidden=$('expand').hidden=false;initWorld();render()}
 }});spaceSession=created;opening=false;
}
function drawingHands(mode='drawing'){if(spaceSession)return;world.pause(true);$('world').hidden=$('flatCanvas').hidden=pins.hidden=true;$('flat').hidden=$('expand').hidden=true;spaceSession=(mode==='result'?mountControl:mode==='sensor'?mountSensors:mountDrawing)({stage:$('stage'),panel,day,flat,onChange:hud,checkSession,onExit:returnHall,onComplete(){spaceSession.dispose();spaceSession=null;atStation=false;pins.hidden=false;$('flat').hidden=$('expand').hidden=false;day.next(mode);initWorld();render()}})}
function results(){const names={docked:'도킹 범위 안 정지',fast:'접근 속도 큼',offset:'중심 벗어남',fuel:'연료 부족',timeout:'시간 종료',stopped:'중지 기록'};return `<div class="trial-list">${day.spaceResults.map((r,i)=>`<article><b>${i+1}차 · ${names[r.status]}</b><p>질량 ${r.config.mass} · 추력 ${r.config.power} · 안정 보조 ${r.config.assist?'켬':'끔'}<br>중심 오차 ${r.offset} · 접근 속도 ${r.speed} · 연료 사용 ${r.fuelUsed}</p></article>`).join('')}</div>`}
function render(){if(!checkSession())return;hud();document.body.classList.toggle('judging',day.stage===7&&atStation);pins.hidden=day.stage===0||day.stage===10;world?.setTask(STEPS[day.stage].station);const step=STEPS[day.stage];say(`${step.team} 무전 · “${step.radio}”`);
 if(day.stage===0){if(needsWhoCheck()){show('<h2>누구의 기록인가요?</h2>'+button('keep','내 기록이에요')+button('new','새로 출근하는 사람이에요'));$('keep').onclick=()=>{keepSession();render()};$('new').onclick=()=>{session=startNewSession().id;render()};return}
 show(`<p class="eyebrow">오늘의 명찰 · 항공우주공학기술자</p><h1>오후 4시,<br>무인 화물선 도킹.</h1>${button('start','명찰 달고 시험동으로 →')}<div class="wd-card"><ul><li>도킹 장치의 도면과 조립 상태를 확인해요.</li><li>지상 조종석에서 시험하고 결과를 비교해요.</li><li>진행·보류 의견과 기록을 관제에 전달해요.</li></ul><p>09:00–18:00 · 휴식 60분<br>시급 ${won(salaryDay(JOB.annual,480).hourly)} · 8시간 일당 ${won(day.pay.base)}</p><small>커리어넷 151 · 워크넷 2021년 항공공학기술자 자료</small></div>${wallet()}${loadMine().length?button('send','선생님께 출근 기록 보내기'):''}${button('new','새로 출근하는 사람이에요')}<p>${home}</p><p class="fine">가상 일터의 지상 시험을 단순화했어요. 실제 우주 비행·정비 훈련이나 적성 판정이 아니에요.</p>`);$('start').onclick=()=>advance();$('new').onclick=()=>{session=startNewSession().id;render()};if($('send'))$('send').onclick=openSendDialog;return}
 if(day.stage===10){endView();return}
 if(!atStation){const station=STATIONS.find(s=>s.id===step.station);show(`<p class="eyebrow">${step.time} · ${step.name}</p><h2>${station.name}에서 만나요.</h2><p>장소 표시를 누르면 내가 걸어가요. 바닥을 눌러 자유롭게 둘러볼 수도 있어요.</p>${button('goWork',station.name+' · 걸어가기 →')}${tracker()}<p>${home}</p>`);$('goWork').disabled=moving;$('goWork').onclick=()=>travel(step.station);return}
 if([1,3,6].includes(day.stage)){hands({1:'prepare',3:'assembly',6:'cockpit'}[day.stage]);return}
 if([2,4,8].includes(day.stage)){drawingHands({2:'drawing',4:'sensor',8:'result'}[day.stage]);return}
 const back=button('backHall','← 시험동 둘러보기');let content='';
 if(day.stage===2)content=`<h2>오늘의 접속부 도면이에요.</h2><div class="blueprint" aria-label="무인 화물선과 도킹 장치 개요"><span>무인 화물선</span><b>▰ ── ◎ ── ▣</b><span>화물선 → 도킹 장치 → 정거장</span></div><p>오후 4시 접속할 장치예요. 조립대에서 체결부를 확인하고 조종석에서 접근을 시험해요.</p>${button('drawingDone','도면 확인 · 제작팀에 전달')}`;
 if(day.stage===4)content=`<h2>거리와 중심 신호를 확인해요.</h2><div class="wd-card"><p>◎ 중심 정렬 신호<br>↔ 접근 거리 신호<br>▣ 시험 기록 연결</p></div><p>센서 팀이 준비한 세 항목을 함께 확인하고 오후 시험에 연결해요.</p>${button('sensorDone','센서 팀 확인 기록 받기')}`;
 if(day.stage===5)content=`<h2>점심 먹고 잠깐 쉬어요.</h2><p>오후에는 같은 장치를 조종석에서 시험해요. 지금 60분은 근무 시간에 넣지 않는 휴식이에요.</p>${button('rest','몸을 쉬고 점심 먹기')}${button('talk','동료와 가볍게 이야기 나누기')}`;
 if(day.stage===7)content=`<h2>16시 도킹, 어떻게 할까요?</h2><p>체결부: ${day.repaired?'조임 완료':'틈 있음 · 후속 확인 15분'} · 마지막 시험: ${day.spaceResults.at(-1)?.status==='docked'?'범위 안 정지':'안전 범위 확인 못함'}</p><div class="decision-actions">${button('go','16:00 도킹 진행')}${button('hold','보류 · 내일 다시 확인')}</div><details><summary>내 시험 기록 ${day.spaceResults.length}회 펼치기</summary>${results()}</details><p class="fine">진행을 골라도 위험한 결과가 있으면 관제가 접근을 멈춰요. 안전하게 미루는 것도 엔지니어의 일이에요.</p>`;
 if(day.stage===8){const text=day.outcome==='docked'?'관제: “확인한 조건에서 도킹을 마쳤어요.”':day.outcome==='held'?'관제: “의견을 받았어요. 오늘 접근은 보류하고 내일 다시 확인해요.”':'관제: “위험한 접근 징후가 있어 멈췄어요. 시험 기록을 보완하고 내일 다시 해요.”';content=`<h2>${day.outcome==='docked'?'오늘의 도킹 결과':'오늘은 안전하게 멈췄어요.'}</h2><div class="control-window"><span>관제실 · 무인 화물선</span><strong>${day.outcome==='docked'?'◎ ━ ▣':'◎　⋯　▣'}</strong><p>${text}</p></div><p>내 선택: ${day.decision==='go'?'진행':'보류'} · 지상 시험과 체결부 기록을 함께 확인한 결과예요.</p>${button('resultDone','관제 결과를 기록하고 정리하기')}`}
 if(day.stage===9)content=!day.reportChecked?`<h2>다음 팀이 이어 볼 수 있게.</h2><p>${day.ending}.</p><div class="wd-card">체결부 ${day.repaired?'조임 완료':'추가 확인 필요'} · 시험 ${day.spaceResults.length}회<br>내일 확인: ${day.outcome==='docked'?'다른 접근 조건에서도 재검증':'안전한 접근 조건과 중심 정렬'}</div>${button('cleanup','시험기 정리 · 조건과 한계 인계하기')}`:`<h2>18시, 퇴근할 시간이에요.</h2><p>${day.delay?'도면 재확인·체결부 후속 확인 '+day.delay+'분이 남았어요.':'오늘 기록과 시험기를 정리했어요.'}</p>${day.delay?button('stay','남아서 마치기 · '+day.delay+'분 연장'):''}${button('handover',day.delay?'다음 팀에 넘기고 정시 퇴근':'기록을 넘기고 정시 퇴근')}`;
 show(`<p class="eyebrow">${day.stage===9&&day.reportChecked?'18:00 · 퇴근 준비':step.time+' · '+step.name}</p>${content}${back}${tracker()}`);$('backHall').onclick=()=>{atStation=false;render()};
 for(const [id,choice]of [['drawingDone','drawing'],['sensorDone','sensor'],['rest','rest'],['talk','talk'],['go','go'],['hold','hold'],['resultDone','result'],['stay','stay'],['handover','handover']])if($(id))$(id).onclick=()=>advance(choice);
 if($('cleanup'))$('cleanup').onclick=()=>{if(checkSession()&&day.cleanup())render()};
}
function endView(){const p=day.pay;say('다온: “결과를 바탕으로 다음 질문을 만든 것도 오늘 한 일이에요.”');show(`<p class="eyebrow">퇴근 · ${18+Math.floor(day.overtime/60)}:${String(day.overtime%60).padStart(2,'0')}</p><h2>오늘 번 일당 · 세전</h2><div class="pay">${won(p.total)}</div><p class="pay-note">${PAY_NOTE}</p><table class="wd-slip"><tr><td>기본급 · ${won(p.hourly)} × 8시간</td><td>${won(p.base)}</td></tr>${p.overMin?`<tr><td>연장 ${p.overMin}분 · 1.5배</td><td>${won(p.overtime)}</td></tr>`:''}</table><details><summary>이 일당은 어떻게 나왔을까?</summary><p>커리어넷 151, 워크넷 2021년 항공공학기술자 연봉 중앙값 5,450만 원. 연봉 ÷ 12 ÷ 209를 10원 단위로 반올림해요. 2026년 최저시급 ${won(MIN_WAGE.hourly)}와 비교해 ${p.floored?'최저시급':'자료 시급'}을 적용했어요. 실제 급여와 달라요.</p><a href="${careernetUrl('151')}" target="_blank" rel="noopener">직업정보 출처</a><p>직업끼리 일당으로 순위를 매기지 않아요.</p></details><p>남은 힘 ${day.energy} · 인계 ${day.delay-day.overtime}분</p><h2>퇴근길 돌아보기</h2><p>${day.ending}</p>${MOMENTS.map((m,i)=>`<div class="wd-moment">${m.label}<br><button data-like="${i}" aria-pressed="${like===i}">💛 끌림</button><button data-hard="${i}" aria-pressed="${hard===i}">🪨 버거움</button></div>`).join('')}<p id="interest"></p><p class="fine">순간 하나로 나를 정할 수는 없어요. 여러 직업을 경험하고 흥미검사와도 견주어 보세요.</p>${button('save','출근 기록 남기기')}<p id="status" role="status"></p><div id="walletSummary">${wallet()}</div>${button('send','선생님께 출근 기록 보내기')}${button('again','같은 직업 다시 하기')}<p>${home}</p>`);const update=()=>{$('save').disabled=saved||like===null||hard===null||like===hard;$('send').hidden=!saved;$('interest').textContent=[like,hard].filter(i=>i!==null).map(i=>`${MOMENTS[i].label}: ${RIASEC[MOMENTS[i].type].name} 쪽의 일이에요.`).join(' ');for(const b of panel.querySelectorAll('[data-like],[data-hard]')){b.disabled=saved||!!day.record;b.setAttribute('aria-pressed',String(b.dataset.like!==undefined?Number(b.dataset.like)===like:Number(b.dataset.hard)===hard))}};panel.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{like=Number(b.dataset.like);update()});panel.querySelectorAll('[data-hard]').forEach(b=>b.onclick=()=>{hard=Number(b.dataset.hard);update()});$('save').onclick=()=>{if(!checkSession()||$('save').disabled)return;try{const result=saveRecordSafe(day.make(like,hard));saved=result.ok;update();if(saved)$('walletSummary').innerHTML=wallet();$('status').textContent=saved?'출근 기록을 남겼어요. 다시 눌러도 한 번만 저장해요.':'저장하지 못했어요. 기기 저장을 허용한 뒤 다시 눌러요.'}catch(e){$('status').textContent=e.message}};$('send').onclick=()=>checkSession()&&openSendDialog();$('again').onclick=()=>location.reload();update();}initWorld();render();
